insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('el-precio-de-estar-vivo','El precio de estar vivo','Las consecuencias de nuestros actos no como reglas quebrantadas, sino como el precio de estar vivo, del inevitable roce con el mundo y los demás.','','roce','ensayo','es',array['vida','familia']::text[],'2026-10-14',9,null,false) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('9-segundos','9 segundos','El caso PocketOS demuestra que la gobernanza de IA es arquitectura, no cosmética. Trazabilidad pre-acción, separación de responsabilidades y marco de confianza medible son capas que deben existir por diseño — no después como autopsia.','','criterio','ensayo','es',array['gobernanza','arquitectura']::text[],'2026-04-30',7,'https://www.linkedin.com/pulse/9-segundos-jorge-l-amparán-lmfvf/',true) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('inteligencia-organizacional-el-eslabon-perdido','Inteligencia organizacional, el eslabón perdido','Cuando un colaborador se va, lo que pierde la organización no son procesos sino criterio acumulado. Documentar no es lo mismo que aprender — y capturar el flujo de trabajo en el momento en que ocurre es hoy técnicamente posible y estratégicamente medible.','','criterio','ensayo','es',array['organizacion','soberania']::text[],'2026-03-26',6,'https://www.linkedin.com/pulse/inteligencia-organizacional-el-eslabón-perdido-jorge-l-amparán-soeqe/',true) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('soberania-la-llave-que-me-dio-mi-padre-una-noche','Soberanía: la llave que me dio mi padre una noche','Una IA que opera sin acceso a fuentes externas verificadas y gobernadas no es inteligencia — es eco. La soberanía operativa de un sistema no está en el modelo, está en la calidad y arquitectura del conocimiento al que accede.','','criterio','ensayo','es',array['soberania','familia']::text[],'2026-03-14',8,'https://www.linkedin.com/pulse/soberanía-la-llave-que-me-dio-mi-padre-una-noche-jorge-l-amparán-n4ywe/',true) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('lo-que-aprendi-debajo-de-un-auto','Lo que aprendí debajo de un auto que Amazon aún no sabe','Una válvula gobernadora controla el flujo hidráulico, no lo aprueba después de que ocurra. La gobernanza de IA tiene que estar en la arquitectura — no como guardrail de emergencia.','','criterio','ensayo','es',array['gobernanza','arquitectura']::text[],'2026-03-10',6,'https://www.linkedin.com/pulse/lo-que-aprendí-debajo-de-un-auto-amazon-aún-sabe-jorge-l-amparán-l4cif/',true) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('guardrails-and-policies-are-not-governance','Guardrails & Policies Are Not Governance. They''re Cosmetics','Real AI governance is a chain of four architectural layers — normalization, contextual knowledge, decision traceability, visibility — applied to the foundations of the system, not added as containment after deployment.','','criterio','ensayo','en',array['gobernanza','arquitectura']::text[],'2026-03-05',7,'https://www.linkedin.com/pulse/guardrails-policies-governance-theyre-cosmetics-jorge-l-amparán-s7gje/',true) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('the-day-the-cloud-burned','The Day the Cloud Burned','A drone strike on a Dubai data center turned an invisible assumption visible: critical operational intelligence has been quietly migrating to infrastructure with physical addresses, walls, and coordinates. Sovereignty isn''t a feature — it''s an architecture decision.','','criterio','ensayo','en',array['soberania']::text[],'2026-03-01',5,'https://www.linkedin.com/feed/update/urn:li:activity:7434995107260702720/',true) on conflict (slug) do nothing;
insert into escritos (slug,titulo,bajada,cuerpo_md,serie,tipo,idioma,temas,fecha,minutos,origen_url,publicado) values ('on-mckinseys-sovereign-ai-forecast','On McKinsey''s $600B Sovereign AI Forecast','Sovereign AI initiatives stall not from lack of investment but from chasing isolated assets instead of designing ecosystems. The Juárez–El Paso corridor moves 20% of U.S.–Mexico trade across three jurisdictions; that''s not a technology problem, it''s an architecture problem.','','criterio','comentario','en',array['soberania','organizacion']::text[],'2026-02-15',4,'https://www.linkedin.com/feed/update/urn:li:activity:7434714696093646849/',true) on conflict (slug) do nothing;
